INSERT INTO diagnostic_nodes VALUES ('no-crank','crank','question','Does the engine turn over when you try to start it?','Cranking means the engine rotates, even if it does not fire. This separates no-crank from crank-but-no-start complaints.');
INSERT INTO diagnostic_nodes VALUES ('no-crank','lights','question','Do the dashboard lights come on?','Missing dashboard power can indicate a discharged battery, connection problem, or power-distribution fault.');
INSERT INTO diagnostic_nodes VALUES ('no-crank','clicks','question','Do you hear rapid repeated clicks when attempting to start?','Repeated clicks can occur when voltage falls under starter load. This does not by itself prove the battery is faulty.');
INSERT INTO diagnostic_nodes VALUES ('no-crank','single','question','Do you hear one solid click when attempting to start?','A single click suggests some control activity, but the battery, cables, starter, or mechanical resistance can still be involved.');
INSERT INTO diagnostic_nodes VALUES ('no-crank','interlock','question','Does the dashboard show a security or key-not-recognized warning?','An immobilizer or key-recognition issue may prevent a start request.');
INSERT INTO diagnostic_nodes VALUES ('no-crank','selector','question','For an automatic transmission, does starting in Neutral work when Park does not?','With the brake held and parking brake applied, follow the owner manual. A difference can point toward range-selection sensing. For a manual transmission or if unsure, choose unknown.');
INSERT INTO diagnostic_nodes VALUES ('no-crank','other','result','This is a crank-but-no-start complaint.','The engine rotates, so this starter questionnaire is not the appropriate path. Fuel, ignition, and engine-management checks need a separate guide.');
INSERT INTO diagnostic_nodes VALUES ('no-crank','power','result','Possible loss of battery or main electrical supply.','Check whether other electrical equipment works. With the ignition off, visually inspect accessible battery connections without touching damaged wiring. Have battery condition, connections, and main power distribution tested.');
INSERT INTO diagnostic_nodes VALUES ('no-crank','supply','result','Possible low voltage or excessive resistance in the starting supply.','Repeated clicking supports checking battery charge and condition plus cable connections. A battery load test and cable voltage-drop tests can distinguish these causes.');
INSERT INTO diagnostic_nodes VALUES ('no-crank','load','result','Possible starter supply, starter, or mechanical problem.','A single click cannot identify the failed part. Request battery testing and starting-circuit voltage-drop tests before condemning the starter; mechanical resistance may also need checking.');
INSERT INTO diagnostic_nodes VALUES ('no-crank','security','result','Possible key-recognition or immobilizer issue.','Follow the owner manual for the displayed warning and, if available, try the approved spare key. Do not bypass the immobilizer.');
INSERT INTO diagnostic_nodes VALUES ('no-crank','range','result','Possible transmission range-sensing or selector adjustment issue.','Starting in Neutral but not Park supports inspection of the range sensor and selector mechanism. Arrange repair; do not bypass the start interlock.');
INSERT INTO diagnostic_nodes VALUES ('no-crank','control','result','Starting control circuit needs further diagnosis.','Possible causes include an interlock, fuse, relay, ignition switch, wiring, or starter circuit fault. Check the owner manual for starting requirements; use vehicle-specific wiring and test procedures for further work.');
INSERT INTO diagnostic_nodes VALUES ('no-crank','inspection','result','More observation or a hands-on inspection is needed.','An unknown answer is not evidence that a component failed. Ask someone to help identify the sound or observation safely, or arrange inspection. Restart when you have more information.');
